mapper.select:
select a.* from ( select row_number() over(order by media_id desc) as num , media_id , media_name , media_div , director , actor , producer , distributor , author , channel , open_date , period , running_time , rating_grade , genre , introduce , media_code , `rank` , audiAcc , save_date from media m where 1=1
and ( media_name like concat('%', #{searchText}, '%') or director like concat('%', #{searchText}, '%') or genre like concat('%', #{searchText}, '%') )
and media_div = #{media_div}
order by
num ${orderType}
media_id ${orderType}
num desc
limit #{firstIndex}, #{recordCountPerPage} ) a

select count(*) as tot_cnt from media where 1=1
and media_name like concat('%', #{searchText}, '%')
and media_div = #{media_div}
